-- ============================================================================
-- B5 FOLLOW-ON W4a (typed-case panel modes): perfsand.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1
-- route (b), and docs/graded-field-audit/w4a/perfsand.json. Owner approved D1
-- to D7 as recommended, 2026-09-21 (D2: the panel guard forbids a DEFAULT
-- state that lands on a graded answer; typing the case is the work).
--
-- ADVANCED
--   Fields 3 to 6 screen 2200 to 2320 m MD, and the Sanding onset view took the
--   cavity, step and boost but not the interval. W4a adds Top and Bottom boxes
--   (blank is the published 2450 to 2550 m) passed to all four sanding calls,
--   and prints the zero-margin boost to 8 dp. The brief now names the view.
--   Prompt only.
--   PROMPT was: Report: (1) the MINIMUM of the Saucier gravel band in metres;
--   PROMPT now: The sand control explorer's Sanding onset view takes this
--   interval, step, cavity and boost as typed inputs. Report: (1) the MINIMUM of
--   the Saucier gravel band in metres;
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after.
--
-- ATTEMPTS. Prompt copy only: no graded key or tolerance moves, so no attempt
-- can be graded differently and there is no attempts guard.
--
-- GUARDS. Each row must hold EITHER its live prompt (by md5) and fields (exact
-- jsonb) as the W1-state scratch replay has them (it is rewritten), OR its W4a
-- form (left alone). Anything else raises and the whole file rolls back. A
-- file that will write first checks that W1 is applied and refuses without it.
-- Generated by docs/graded-field-audit/w4a_capstones.py. SAFE TO RE-RUN: a
-- second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- perfsand / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w4a perfsand refused: perfsand/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '79d9f8e3c894368cb67c7bb5ed21b5dd' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb then 'old'
              when md5(prompt) = '0b70da75fa56c6775396d61f376f5dae' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w4a perfsand refused: perfsand/advanced matches neither its live form (prompt md5 79d9f8e3c894368cb67c7bb5ed21b5dd) nor its W4a form (prompt md5 0b70da75fa56c6775396d61f376f5dae), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W4a form
  if v_s0 = 'new' then
    raise notice 'w4a perfsand: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active and md5(prompt) = '27fc6852586864af77f23cdbbf2deacc')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'petrophysics' and c.tier = 'advanced' and c.active and f->>'key' = 'sw_waterleg_mean'
                   and (f->>'tol')::float8 = 0.005) then
    raise exception 'w4a perfsand refused: W1 (20261024a/b) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Six values. THE SAND is the Associate capstone sieve, cumulative retained in microns: 560 at 2, 400 at 7, 280 at 19, 200 at 36, 140 at 54, 100 at 70, 70 at 83, 50 at 92 and 38 at 96. THE INTERVAL runs from 2200 to 2320 m measured depth, screened at a step of 25 m, as an OPEN HOLE cavity, with a strength boost factor of 1.15. The sand control explorer''s Sanding onset view takes this interval, step, cavity and boost as typed inputs. Report: (1) the MINIMUM of the Saucier gravel band in metres; (2) the GAUGE MARGIN in metres, meaning the largest permissible gauge less the gauge actually selected; (3) the CRITICAL FLOWING PRESSURE at the governing station in pascals; (4) the GOVERNING critical drawdown pressure in pascals; (5) the critical drawdown pressure at the BOTTOM station in pascals; and (6) the boost factor at which the governing margin is exactly ZERO. Traps. The Saucier band is a multiplier on D50 and NOT on D10, and using the coarse percentile oversizes the pack by a factor of well over two. The gauge series is DISCRETE, so field 2 is a leftover and not a design choice, and it is the bound less the SELECTED gauge rather than the bound less the gravel size. The step does NOT divide the interval: 120 m at 25 m gives 2200, 2225, 2250, 2275, 2300 and then a CLAMPED bottom at 2320, which is SIX rows and not five, and the sixth exists only because the engine walks to the interval bottom rather than to the last whole step before it. Fields 4 and 5 are DIFFERENT numbers and field 4 is the SMALLER: on this interval the TOP station governs, so a learner who assumes the deepest row is the worst one reports field 5 twice. Field 6 is a search and not a formula. Free checks: field 5 must EXCEED field 4, since the governing value is a minimum over the rows; field 6 must be BELOW the applied 1.15, because at 1.15 the interval still has margin; and field 1 must equal five times the Associate tier D50 exactly.'
     where app_slug = 'perfsand' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w4a perfsand refused: perfsand/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '0b70da75fa56c6775396d61f376f5dae' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb) from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active) is not true then
    raise exception 'w4a perfsand refused: perfsand/advanced does not read back as its W4a form';
  end if;

  raise notice 'w4a perfsand: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
